sections.body:
保存为 subtitle-track.mjs，用 node subtitle-track.mjs 运行。时间范围采用左闭右开：到达 startMs 显示，到达 endMs 清除；相邻两句边界相同时只显示下一句。这里只处理已批准的单轨，不解析 Whisper JSON，也不播放音频。

```javascript
/**
 * @file Validate a single subtitle track and query it by the audio clock.
 * @author liliwei
 * @date 2026-10-28
 * @LastEditors liliwei
 * @LastEditTime 2026-10-28
 */
/** @typedef {{id:string,startMs:number,endMs:number,text:string}} Cue */
/**
 * Validate without sorting or changing the input.
 * @param {Cue[]} rows Ordered, non-overlapping subtitle cues.
 * @param {number} durationMs Positive integer duration in milliseconds.
 * @returns {ReadonlyArray<Readonly<Cue>>} A frozen copy.
 */
export function compileCues(rows, durationMs) {
  if (!Array.isArray(rows) || !Number.isSafeInteger(durationMs) ||
      durationMs <= 0) throw new Error("invalid track");
  const ids = new Set();
  let previousEnd = 0;
  return Object.freeze(Array.from(rows, row => {
    if (!row || typeof row.id !== "string" || !row.id.trim() ||
        ids.has(row.id) || typeof row.text !== "string" || !row.text.trim() ||
        !Number.isSafeInteger(row.startMs) || !Number.isSafeInteger(row.endMs) ||
        row.startMs < previousEnd || row.endMs <= row.startMs ||
        row.endMs > durationMs) throw new Error("invalid cue");
    ids.add(row.id);
    previousEnd = row.endMs;
    return Object.freeze({
      id: row.id, startMs: row.startMs, endMs: row.endMs, text: row.text
    });
  }));
}
/**
 * Find the cue in [startMs, endMs), including after a backward seek.
 * @param {ReadonlyArray<Readonly<Cue>>} cues Result of compileCues.
 * @param {number} timeMs Current audio time in milliseconds.
 * @returns {Readonly<Cue>|null} Active cue, or no subtitle.
 */
export function cueAt(cues, timeMs) {
  if (!Number.isFinite(timeMs) || timeMs < 0) return null;
  let lo = 0, hi = cues.length;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (cues[mid].startMs <= timeMs) lo = mid + 1;
    else hi = mid;
  }
  const cue = cues[lo - 1];
  return cue && timeMs < cue.endMs ? cue : null;
}
const cues = compileCues([
  { id: "a", startMs: 500, endMs: 2000, text: "别碰那盏灯。" },
  { id: "b", startMs: 2500, endMs: 4000, text: "先找回星砂。" },
  { id: "c", startMs: 4000, endMs: 5500, text: "再回来开门。" }
], 6000);
const times = [0, 500, 2000, 2500, 4000, 5500, 4500, 1000, 1000];
console.log(times.map(t => cueAt(cues, t)?.id ?? null));
```

本次将正文代码原样提取到 Node.js 22.16.0 执行，九个查询得到 [null, "a", null, "b", "c", null, "c", "a", "a"]。

| 人工时间点 | 应显示什么 | 检查目的 |
| --- | --- | --- |
| 0ms / 500ms | 空 / a | 片头留白与进入边界 |
| 2000ms / 2500ms | 空 / b | 句间留白不能延续旧字幕 |
| 4000ms / 5500ms | c / 空 | 相邻交界与末句结束 |
| 5500 → 4500 → 1000ms | 空 → c → a | 往回拖动仍能查询 |
| 连续两次 1000ms | a、a | 模拟暂停时音频时钟不前进 |

加载时校验一次，查询不依赖“上一句”指针，所以无需为倒退补一串定时器。代码拒绝重叠、倒序、重复 ID、越界、空文字和非法时间；空轨合法，查询返回 null。返回值被冻结，避免之后误改边界。

这些毫秒值和文字由人构造，结果仅验证规则。它们没有证明模型识别准确，也没有证明浏览器或手机实际同步精度。
